lemma timeSlice_spatial_deriv {M : Type}
    [NormedAddCommGroup M] [NormedSpace ℝ M] {d : ℕ} {f : SpaceTime d → M}
    {t : Time} {x : Space d}
    (hdiff : DifferentiableAt ℝ f (toTimeAndSpace.symm (t, x))) (i : Fin d) :
    timeSlice (∂_ (Fin.natAdd 1 i) f) t x = ∂[i] (timeSlice f t) x

lemma timeSlice_time_deriv {M : Type}
    [NormedAddCommGroup M] [NormedSpace ℝ M] {d : ℕ} (f : SpaceTime d → M)
    {t : Time} {x : Space d}
    (hdiff : DifferentiableAt ℝ f (toTimeAndSpace.symm (t, x))) :
    timeSlice (∂_ (finSumFinEquiv (Sum.inl 0)) f) t x = ∂ₜ (fun t => timeSlice f t x) t

lemma PermCond.auto {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C}
    {σ : Fin m → Fin n} (h : PermCond c c1 σ := by {simp [PermCond]; try decide}) :
    PermCond c c1 σ

lemma PermCond.apply_inv_apply {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C}
    (σ : Fin m → Fin n) (h : PermCond c c1 σ) (x : Fin m) :
    h.inv σ (σ x) = x

lemma PermCond.inv_apply_apply {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C}
    (σ : Fin m → Fin n) (h : PermCond c c1 σ) (x : Fin n) :
    σ (h.inv σ x) = x

lemma PermCond.inv_perserve_color {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C}
    {σ : Fin m → Fin n} (h : PermCond c c1 σ) (x : Fin n) :
    c1 (h.inv σ x) = c x

