def dropPair {n : ℕ} {c : Fin (n + 1 + 1) → S.C}
    (i j : Fin (n + 1 + 1)) (b : ComponentIdx c) :
    ComponentIdx (c ∘ Pure.dropPairEmb i j)

def DropPairSection {n : ℕ} {c : Fin (n + 1 + 1) → S.C}
    {i : Fin (n + 1 + 1)} {j : Fin (n + 1 + 1)}
    (b : ComponentIdx (c ∘ Pure.dropPairEmb i j)) :
    Finset (ComponentIdx c)

lemma mem_iff_apply_dropPairEmb_eq {n : ℕ} {c : Fin (n + 1 + 1) → S.C}
    {i j : Fin (n + 1 + 1)}
    (b : ComponentIdx (c ∘ Pure.dropPairEmb i j))
    (b' : ComponentIdx c) :
    b' ∈ DropPairSection b ↔
      ∀ m, b' (Pure.dropPairEmb i j m) = b m

@[simp]
lemma mem_self_of_dropPair {n : ℕ} {c : Fin (n + 1 + 1) → S.C}
    {i j : Fin (n + 1 + 1)}
    (b : ComponentIdx (c)) :
    b ∈ DropPairSection (b.dropPair i j)

lemma basis_repr_apply {n : ℕ} {c : Fin n → S.C}
    (f : TensorInt S c) (b : ComponentIdx c) :
    (Tensor.basis c).repr (toTensor f) b = Int.cast (f b)

lemma basis_eq_tensorInt {n : ℕ} {c : Fin n → S.C}
    (b : ComponentIdx c) :
    Tensor.basis c b = TensorInt.toTensor (fun b' => if b = b' then 1 else 0)

lemma Pure.prodP_zero_right {n} {c : Fin n → S.C}
    {c1 : Fin 0 → S.C} (p : Pure S c) (p0 : Pure S c1) :
    prodP p p0 = permP id (prodP_zero_right_permCond) p

lemma contrT_basis_repr_apply_eq_fin {n d: ℕ} {c : Fin (n + 1 + 1) → (realLorentzTensor d).C}
    {i j : Fin (n + 1 + 1)}
    {h : i ≠ j ∧ (realLorentzTensor d).τ (c i) = c j}
    (t : ℝT(d,c)) (b : ComponentIdx (c ∘ Pure.dropPairEmb i j)) :
    (basis (c ∘ Pure.dropPairEmb i j)).repr (contrT n i j h t) b =
    ∑ (x : Fin (1 + d)),
    ((basis c).repr t
    (DropPairSection.ofFinEquiv h.1 b ⟨Fin.cast (by simp) x, Fin.cast (by simp) x⟩))

